import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.aJDz64y9.js";const f=JSON.parse('{"title":"Ресёрч: что забираем из референсов","description":"","frontmatter":{},"headers":[],"relativePath":"crime/research.md","filePath":"crime/research.md","lastUpdated":1794540927000}'),n={name:"crime/research.md"};function o(i,t,s,l,h,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="ресерч-что-забираем-из-референсов" tabindex="-1">Ресёрч: что забираем из референсов <a class="header-anchor" href="#ресерч-что-забираем-из-референсов" aria-label="Permalink to &quot;Ресёрч: что забираем из референсов&quot;">​</a></h1><p>Сильные криминальные механики в референсах устроены одинаково: подготовка меняет исход, время внутри ограничено, место под добычу ограничено, а сбыт — отдельный риск.</p><table tabindex="0"><thead><tr><th>Референс</th><th>Что там работает</th><th>Что забираем</th></tr></thead><tbody><tr><td><a href="https://gta.wiki/w/Heists_in_GTA_V" target="_blank" rel="noreferrer">GTA V: устройство ограблений</a></td><td>План у Лестера, выбор подхода, найм специалистов. Дорогой эксперт берёт большую долю, дешёвый может сорваться; выжившие растут в навыке. Перед делом — миссии за оружием, газом, транспортом, формой</td><td>Подход как выбор. Подготовка как отдельный геймплей. Навык растёт от практики</td></tr><tr><td><a href="https://gta.wiki/wiki/The_Jewel_Store_Job" target="_blank" rel="noreferrer">GTA V: ювелирный</a></td><td>Тихий вариант требует двух подготовок, громкий — одной. От хакера зависит, сколько секунд молчит сигнализация, пока команда бьёт 20 витрин. Слабый стрелок роняет часть добычи</td><td>Таймер задаёт сама команда качеством подготовки. Добычу можно потерять на отходе</td></tr><tr><td><a href="https://gta.wiki/w/Robberies" target="_blank" rel="noreferrer">GTA V и Online: налёты на магазины</a></td><td>Продавец под прицелом сам складывает деньги в пакет. В Online шкала запугивания растёт от стрельбы по товару и от угроз в голосовой чат. Продавец может достать оружие. Серия налётов в одной маске поднимает розыск до пяти звёзд</td><td>Голос как инструмент давления. Серия без смены облика повышает риск</td></tr><tr><td><a href="https://gta.wiki/w/Burglar" target="_blank" rel="noreferrer">GTA SA: Burglar</a></td><td>Работает с 20:00 до 06:00, нужен фургон. Шкала шума растёт от бега и открывания дверей; когда она заполнена, есть 10 секунд до вызова полиции. Телевизоры, приставки и микроволновки носят к фургону по одной. Оплата: 20 × (число предметов)²</td><td>Шум. Физический вынос вещей. Фургон как вместимость. Большой рейс платит непропорционально больше</td></tr><tr><td><a href="https://www.gtabase.com/gta-online/jobs/heists/the-diamond-casino-heist" target="_blank" rel="noreferrer">Online: Diamond Casino Heist</a></td><td>Три подхода, один и тот же нельзя брать дважды подряд. Нанятый хакер даёт от 2:26 до 3:30 в хранилище, а если команду заметили — от 1:42 до 2:26. Добыча бывает четырёх видов: наличные, картины, золото, бриллианты</td><td>Тревога не проваливает дело, а отнимает время. Содержимое цели меняется от раза к разу</td></tr><tr><td><a href="https://gta.wiki/w/The_Cayo_Perico_Heist" target="_blank" rel="noreferrer">Online: Cayo Perico Heist</a></td><td>Разведка под прикрытием находит цель, вторичную добычу и входы. Резак, коды сейфа, клонер отпечатков добываются заранее; три диверсии ослабляют охрану. Золото и картины лежат за дверями, которые открываются только вдвоём</td><td>Разведка открывает варианты. Инструмент решает, что можно взять. Дверь на двоих</td></tr><tr><td><a href="https://www.pcgamesn.com/grand-theft-auto-v/gta-online-kortz-center-heist" target="_blank" rel="noreferrer">Online: Kortz Center Heist, июль 2026</a></td><td>Ограбление музея: скрытно сфотографировать цели, заказать подделки и подменить подлинники. Искусство, о краже которого известно, сбывается труднее и дешевле</td><td>Тихая кража стоит дороже громкой — на этом построена «палёность»</td></tr><tr><td><a href="https://www.gtabase.com/gta-online/jobs/vehicle-cargo" target="_blank" rel="noreferrer">Online: Import/Export</a></td><td>Угон под заказ в <a href="https://gta.wiki/w/Vehicle_Cargo/Steal_Missions" target="_blank" rel="noreferrer">разных сценариях</a>: машина припаркована, едет с владельцем, стоит на сходке, заминирована. Ремонт вычитается из прибыли, до $34 000. Три канала продажи топ-класса: частник — $40 000 без вложений, салон — $60 000, спецдилер — $80 000</td><td>Сценарии угона. Аккуратная езда — это деньги. Выбор между «быстро и дёшево» и «с подготовкой и дорого»</td></tr><tr><td><a href="https://gtabase.com/gta-online/property-types/salvage-yards" target="_blank" rel="noreferrer">Online: Salvage Yard</a></td><td>С декабря 2023: три угона в неделю, каждый — разведка, подготовка, финал. Затем выбор: отвезти машину в доки, откуда она уходит в контейнере, или разобрать на запчасти. Эвакуатор свозит брошенные машины под разбор</td><td>Порт как точка сбыта. Развилка «продать целиком или разобрать»</td></tr><tr><td><a href="https://gta.wiki/w/Gun_Van" target="_blank" rel="noreferrer">Online: Gun Van</a></td><td>Торговец оружием в фургоне: 30 возможных точек, переезд раз в сутки, на карте виден с 500 метров</td><td>Кочующий барыга</td></tr><tr><td>ROB RUN: <a href="https://store.steampowered.com/app/4262460/ROB_RUN/" target="_blank" rel="noreferrer">Steam</a>, <a href="https://robrunwiki.org/looty-bay/heists/" target="_blank" rel="noreferrer">ограбления</a>, <a href="https://robrunwiki.org/looty-bay/selling-loot/" target="_blank" rel="noreferrer">сбыт</a></td><td>Ранний доступ с 4 ноября 2026, студия Kefir; полицейские и грабители — живые игроки. Сначала отключают сигнализацию у щитка или панели, потом держат персонал под прицелом. Задняя дверь вскрывается отмычкой, и с улицы магазин выглядит нетронутым. Добычу забирают удержанием клавиши целыми контейнерами. Ключ из одного магазина открывает сейф в другом. Серия преступлений за одну вылазку повышает добычу и риск. Сдавшийся полицейскому теряет только сумку</td><td>Сигнализация раньше персонала. Задняя дверь. Ключи между объектами. Серия повышает ставки. Сдаться дешевле, чем погибнуть</td></tr><tr><td>FiveM-скрипты: <a href="https://forum.cfx.re/t/qbcore-esx-carboosting-vin-scratching/4819300" target="_blank" rel="noreferrer">бустинг</a>, <a href="https://glitchstudios.gitbook.io/glitchstudios/paid-resources/glitch-house-robbery" target="_blank" rel="noreferrer">кражи из домов</a></td><td>Контракты на угон по классам от D до S+. Машина каждые 20 секунд шлёт сигнал полиции, пока пассажир на ходу не отключит трекеры. Перебитый VIN записывается в базу, и полиция может его проверить. В домах — отмычка, шкала шума, точки обыска в интерьерах-«шеллах»</td><td>Техническая основа на FiveM уже отработана. Не хватает людей в цепочке — их и добавляем</td></tr></tbody></table><p>Чего брать не надо. В ROB RUN точки сбыта караулят другие игроки: около 43% из почти 7 000 отзывов в Steam отрицательные, и среди главных претензий — засады у скупщиков и дисбаланс PvP (<a href="https://gamerant.com/games-like-gta-6-rob-run-reviews/" target="_blank" rel="noreferrer">Game Rant</a>). В GTA Online все контрагенты — NPC. В обоих случаях между преступником и деньгами нет людей; концепция ставит туда механика, мастера и скупщика-игрока.</p>',4)])])}const c=e(n,[["render",o]]);export{f as __pageData,c as default};
